<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo WebVerbs</title><link rel="stylesheet" href="demo-style.css?v=4"><style>.result strong{font-size:1.5rem}.history span{margin:4px}</style></head><body><nav class="demo-nav"><div class="demo-nav-inner"><a class="brand" href="../index.php#proyectos">← Volver al portafolio</a><a class="btn primary" href="#">GitHub pendiente</a></div></nav><main class="wrap"><section class="hero"><div><span class="kicker">Aplicación educativa</span><h1>WebVerbs</h1><p>Demo de búsqueda de verbos irregulares en inglés con pasado simple, participio y traducción al español.</p></div><div class="panel"><label>Buscar verbo</label><div style="display:flex;gap:10px;margin-top:10px"><input id="q" value="go"><button class="btn primary" onclick="findVerb()">Buscar</button></div><div id="result" class="card result" style="margin-top:16px"></div></div></section><section class="panel"><h2>Historial</h2><div id="history" class="history"></div></section></main><script>const verbs={go:['went','gone','ir'],eat:['ate','eaten','comer'],write:['wrote','written','escribir'],speak:['spoke','spoken','hablar'],sleep:['slept','slept','dormir']};let h=[];function findVerb(){let k=q.value.trim().toLowerCase();let v=verbs[k];result.innerHTML=v?'<strong>'+k+'</strong><p>Past: '+v[0]+' · Participle: '+v[1]+' · Español: '+v[2]+'</p>':'<strong>No encontrado</strong><p>Prueba con go, eat, write, speak o sleep.</p>';if(k){h.unshift(k);history.innerHTML=h.slice(0,8).map(x=>'<span class="pill">'+x+'</span>').join('')}}findVerb();</script></body></html>
